import{_ as i,a0 as e,w as l,s as d,ao as p,I as o,a1 as n,A as a,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較 | LCTT x X-CMD","titleTemplate":false,"description":"Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20231021 Bitwarden vs. Proton Pass- Comparing Top Open-Source Password Managers","title":"Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較","tag":"202310","desc":""},"relativePath":"202310/20231021 Bitwarden vs. Proton Pass- Comparing Top Open-Source Password Managers.md","filePath":"[post].md"}'),g={name:"202310/20231021 Bitwarden vs. Proton Pass- Comparing Top Open-Source Password Managers.md"};function P(m,t,u,w,f,b){const r=e("Link");return l(),d("div",null,[t[39]||(t[39]=p('<h1 id="bitwarden-與-proton-pass-頂級開源密碼管理器的比較" tabindex="-1">Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較 <a class="header-anchor" href="#bitwarden-與-proton-pass-頂級開源密碼管理器的比較" aria-label="Permalink to “Bitwarden 與 Proton Pass：頂級開源密碼管理器的比較”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/22/075735dk7c6b4raibhkutq.jpg" alt=""></p><blockquote><p>你最鍾愛哪一個開源密碼管理器？</p></blockquote><p>Bitwarden 和 Proton Pass 是兩個傑出的開源密碼管理器。</p><p>Bitwarden 已經成為一個可靠的選擇，運行穩定已經超過六年了，而 Proton Pass 則是較新的參與者。</p><p>你應該選哪一個呢？是<strong>選擇已被大眾信任的密碼管理器還是選擇由以隱私為導向的 Proton 新開發的產品</strong>?</p><p>我一直使用 Bitwarden 和帶高級特性的 Proton Pass。主要使用的是 Bitwarden，但自 Proton Pass 推出後我也在試用它。</p><p>在這裏，我會分享我對兩者的使用體驗，以及在選擇密碼管理器時需要了解的一些注意事項。</p><h3 id="應用場景和應用程序的可用性" tabindex="-1">應用場景和應用程序的可用性 <a class="header-anchor" href="#應用場景和應用程序的可用性" aria-label="Permalink to “應用場景和應用程序的可用性”">​</a></h3><p>選用密碼管理器時，應用程序的可用情況和你的使用場景起着重要角色。</p><p>你需要提些問題給自己：</p><ul><li>我在哪些地方（如桌面、移動設備或網頁瀏覽器）需要密碼管理器？</li><li>它有提供哪些額外功能？</li><li>是否堅持使用一個服務滿足多種功能需求？</li></ul><p>我會在文章的後半部分詳細闡述這些功能特性。但首先，你需要確定你想在哪裏使用密碼管理器，以及是否希望單獨保持密碼管理器服務。</p><h4 id="proton-pass" tabindex="-1">Proton Pass <a class="header-anchor" href="#proton-pass" aria-label="Permalink to “Proton Pass”">​</a></h4><p>在編寫本文時，Proton Pass 僅以 <strong>瀏覽器擴展</strong> 形式存在，同時提供給 <strong>移動平台</strong> 使用。</p><p><img src="https://itsfoss.com/content/images/2023/10/proton-pass.jpg" alt=""></p><p>你可以為 <strong>Mozilla Firefox、Google Chrome、Brave、Edge</strong> 及其它基於 Chrome 的瀏覽器獲取擴展。你也可以選擇在你的 <strong>安卓或 iOS</strong> 設備上安裝它。</p><p><img src="https://itsfoss.com/content/images/2023/10/proton-pass-ui-1.jpg" alt=""></p><p>✅ <em>如果你不需要桌面應用的密碼管理器，同時希望繼續使用 Proton 提供的全部服務，那麼 Proton Pass 是一個適合的選擇。</em></p><h4 id="bitwarden" tabindex="-1">Bitwarden <a class="header-anchor" href="#bitwarden" aria-label="Permalink to “Bitwarden”">​</a></h4><p>反之，Bitwarden 可以作為 <strong>桌面應用</strong>，支持在 <strong>Windows、 macOS、Linux</strong> 上運行。</p><p>此外，你可以為 <strong>Google Chrome、Firefox、Vivaldi, Opera、Edge、Tor 和 DuckDuckGo for Mac</strong> 獲取相應的擴展。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-extension-ui.jpg" alt=""></p><p>對於移動平台來説，Bitwarden 支持 iPhone、Apple Watch 和安卓手機。你也可以從 F-Droid 安裝到安卓設備上。</p><p>還不僅限於這些，你可以將 Bitwarden 作為一款 <strong>網頁應用</strong>，或通過 <strong>命令列接口</strong> 來使用。</p><p>✅ <em>如果你需要一個能夠在多個平台上無縫使用的密碼管理器，那麼 Bitwarden 就是你完美的選擇。</em></p><h3 id="用户體驗" tabindex="-1">用户體驗 <a class="header-anchor" href="#用户體驗" aria-label="Permalink to “用户體驗”">​</a></h3><h4 id="bitwarden-1" tabindex="-1">Bitwarden <a class="header-anchor" href="#bitwarden-1" aria-label="Permalink to “Bitwarden”">​</a></h4><p>Bitwarden 的用户體驗簡潔且低調。</p><p>以下是瀏覽器插件的界面樣式：</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-extension-firefox.jpg" alt=""></p><p>雖然用户界面隨着年份的推移有所改進建，但始終忠於其核心理念，也就是 <strong>注重簡潔而不是華麗的 UI</strong>。</p><p>它不會打擾你的操作，始終提供熟悉的用户體驗。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-login.jpg" alt=""></p><p>你可以在預設的 “dark”、“light”、“solarized dark” 和 “nord” 主題間自由切換。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-theme.jpg" alt=""></p><p>無論你正在使用桌面應用、移動應用還是瀏覽器擴展，它都能給你帶來同樣的便利。</p><h4 id="proton-pass-1" tabindex="-1">Proton Pass <a class="header-anchor" href="#proton-pass-1" aria-label="Permalink to “Proton Pass”">​</a></h4><p>Proton Pass 在其佈局方面 <strong>頗具特色</strong> ，每次你訪問該擴展時，它都會給出一個詳細的憑證概覽。</p><p><img src="https://itsfoss.com/content/images/2023/10/proton-pass-ui-2.jpg" alt=""></p><p>有些用户可能更傾向於 <strong>現代化的 UI 處理方式</strong>，這完全看你的個人喜好。</p><p>我個人更傾向於 Bitwarden 的傳統設計方式。</p><h3 id="價格" tabindex="-1">價格 <a class="header-anchor" href="#價格" aria-label="Permalink to “價格”">​</a></h3><p>你可以免費開始使用這兩種服務。</p><p>Bitwarden 和 Proton Pass 在其免費計劃中都不限制存儲的登錄憑證數量和可使用設備的數量。</p><p>如果你需要包括緊急訪問、家庭共享、安全存儲、二次驗證、電子郵箱別名隱藏等特性，你需要升級為高級版。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-pricing.jpg" alt=""></p>',47)),o("p",null,[n(r,{href:"https://bitwarden.com/pricing/"},{default:a(()=>[...t[0]||(t[0]=[s("Bitwarden",-1)])]),_:1}),t[1]||(t[1]=s(" 的年費僅為 ",-1)),t[2]||(t[2]=o("strong",null,"10 美元",-1)),t[3]||(t[3]=s("，而其家庭計劃（",-1)),t[4]||(t[4]=o("em",null,"包含六個賬户",-1)),t[5]||(t[5]=s("）的年費為 ",-1)),t[6]||(t[6]=o("strong",null,"40 美元",-1)),t[7]||(t[7]=s("。這個價格對大多數人來説是",-1)),t[8]||(t[8]=o("strong",null,"極其實惠",-1)),t[9]||(t[9]=s("的。",-1))]),o("p",null,[t[11]||(t[11]=s("相比之下，",-1)),n(r,{href:"https://account.proton.me/pass/signup"},{default:a(()=>[...t[10]||(t[10]=[s("Proton Pass",-1)])]),_:1}),t[12]||(t[12]=s(" 的價格較高，其 Plus 計劃的年費為 ",-1)),t[13]||(t[13]=o("strong",null,"47.88 歐元",-1)),t[14]||(t[14]=s("。",-1))]),t[40]||(t[40]=p('<p><img src="https://itsfoss.com/content/images/2023/10/protonpass-pricing.jpg" alt=""></p><p>不過，如果你使用了所有其他 Proton 的服務，並選擇了 Proton 的無限制訂閲，你就可以獲得包括 <strong>Proton Pass、Mail、VPN、Drive 和 Calendar</strong> 在內的高級特性。</p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>這兩個密碼管理器功能都十分完善，因此每一種都能提供人們所需要的核心特性。</p><p>它們共同擁有的特性包括：</p><ul><li>密碼生成器</li><li>安全筆記</li><li>自動填充</li><li>卡片信息和登錄憑證</li><li>便於隨時獲取憑證的手機應用</li></ul><p>接下來，讓我來突出一下根據我個人的使用經驗，每一種服務各自獨特的優點：</p><h4 id="bitwarden-2" tabindex="-1">Bitwarden <a class="header-anchor" href="#bitwarden-2" aria-label="Permalink to “Bitwarden”">​</a></h4><p>Bitwarden 的一項關鍵功能是其 “<ruby>發送<rt>Send</rt></ruby>” 功能，它允許你發送一個文件（最大 500 MB）或一段文本/便箋給任何人，這都是通過一個安全連接實現的，並且在整個過程中都實現了端到端的加密。這項功能可以在 <strong>桌面應用、擴展插件和網頁保險庫</strong> 中使用。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-send-web-vault.jpg" alt=""></p><p>你可以通過添加一段只有接收者知道的密碼短語來保護這個鏈接。還有更多的自定義選項，例如設定鏈接的過期時間，或在文件被下載後銷燬鏈接。</p><p>我不認為這是一種安全發送文件的方法，更多的是適合發送私人文件（如電子郵件附件）和文本文件。</p><p>接下來，Bitwarden 提供了一個 <strong>家庭計劃</strong>，允許你與 <strong>其他五個賬户</strong> 共享一個訂閲。Proton Pass 並沒有此類服務。</p><p>我想着重強調的另一個功能是：<strong>緊急訪問</strong>。</p><p>因為密碼管理器儲存了你所有的登錄信息，它就是一個包含 <strong>所有你的訪問密鑰</strong> 的地方。你可以設置緊急訪問功能，以方便你信任的朋友或者家庭成員在你不幸出現緊急狀況後訪問你的密碼。</p><p><img src="https://itsfoss.com/content/images/2023/10/emergency-access-bitwarden.jpg" alt=""></p><p>當然，在授權用户訪問你的賬户之前，你可以設定一個期限以確認或拒絕這個訪問請求。如果你沒有采取任何行動，那麼這個訪問權限將會授予你的信任用户。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-emergency-invite.jpg" alt=""></p>',18)),o("blockquote",null,[o("p",null,[t[16]||(t[16]=s("📋 緊急聯繫人選項只能在 ",-1)),n(r,{href:"https://vault.bitwarden.com/"},{default:a(()=>[...t[15]||(t[15]=[s("網絡保險庫",-1)])]),_:1}),t[17]||(t[17]=s(" 中訪問。",-1))])]),t[41]||(t[41]=p('<p><strong>值得注意的是：</strong> 這兩種服務的密碼生成器都包含歷史記錄，但 Bitwarden <strong>保留歷史時間更長</strong>，而 Proton Pass 只保留一天的歷史記錄。</p><p><img src="https://itsfoss.com/content/images/2023/10/bitwarden-password-generator.jpg" alt=""></p><p>其他功能差異包括：</p><ul><li>導出為 .CSV 文件</li><li>調整自動填充行為</li><li>訪問網絡保險庫</li><li>桌面應用</li><li>記錄身份信息</li></ul><p>對於所有列出的功能，在我使用 Bitwarden 的過程中，我都沒有遇到任何重大的問題。</p><p><strong>我唯一注意到的問題</strong>：有時在我的安卓手機上，自動填充功能並沒有在鍵盤應用中作為建議顯示。當然，這取決於各個智能手機制造商提供的定製安卓體驗，因此不一定是 Bitwarden 特有的問題。</p><h4 id="proton-pass-2" tabindex="-1">Proton Pass <a class="header-anchor" href="#proton-pass-2" aria-label="Permalink to “Proton Pass”">​</a></h4><p>如果我們從“功能數量”上進行比較，Bitwarden 會佔據優勢。</p><p>但是，作為一個以隱私為重點的工具，Proton Pass 實現了密碼管理器所有你需要的重要功能，甚至超越了這些。</p><p><img src="https://itsfoss.com/content/images/2023/10/proton-pass-password-generator.jpg" alt=""></p>',10)),o("p",null,[t[19]||(t[19]=s("得益於對 ",-1)),n(r,{href:"https://simplelogin.io/"},{default:a(()=>[...t[18]||(t[18]=[s("SimpleLogin",-1)])]),_:1}),t[20]||(t[20]=s(" 的專業研究，Proton Pass 支持生成電子郵件別名。",-1))]),o("p",null,[t[22]||(t[22]=s("如果你不太瞭解：SimpleLogin 是最受歡迎的 ",-1)),n(r,{href:"https://itsfoss.com/protect-email-address/"},{default:a(()=>[...t[21]||(t[21]=[s("工具之一，用於保護你的電子郵件地址",-1)])]),_:1}),t[23]||(t[23]=s("。",-1))]),t[42]||(t[42]=p('<p>所以，當 Proton Pass 集成了這個功能後，用户可以 <strong>便捷地創建電子郵件別名</strong>，並同時保存登錄信息。你在 Proton Pass 上註冊的電子郵件將會是實際的電子郵件地址。</p><p>我希望他們提供一個設定新的目標電子郵件地址的選項，這將使 Proton Pass 的額外費用更具價值。</p><p>此外，如果你是一位使用了部分或所有 Proton 服務的用户，使用 Proton Pass 將會是一種良好的用户體驗。因為你無需為其他平台切換或註冊。</p><p>使用 Proton Pass 還可以獲得基本的 <strong>導入/導出，控制某些安全措施，修改密碼管理器行為</strong> 的功能。</p><p><img src="https://itsfoss.com/content/images/2023/10/proton-pass-settings.jpg" alt=""></p><p>因此，對於 Proton 用户而言，Proton Pass 可以是一種一站式的解決方案。</p><p>是的，我暫時沒有注意到任何關於其移動應用的問題，Proton Pass 到目前為止很好。</p><h3 id="你應該選擇哪個" tabindex="-1">你應該選擇哪個？ <a class="header-anchor" href="#你應該選擇哪個" aria-label="Permalink to “你應該選擇哪個？”">​</a></h3><p>考慮到它們的共性，這主要取決於你個人的使用體驗、預算（如果選擇付費），以及功能集。</p><p>對於我個人的使用，我暫時沒有看到 Proton Pass 替換 Bitwarden 的需要。</p><p>然而，如果我決定購買 Proton 的無限制訂閲，或是更加投入到 Proton 的各項服務中去，我可能會放棄 Bitwarden。</p><p>💬 你怎麼認為呢？你認為 Proton Pass 值得額外付費嗎，或者對於 Proton 的捆綁訂閲你有什麼看法？Bitwarden 是你的最愛嗎？歡迎在下方評論分享你的想法。</p><p><em>（題圖：MJ/a2f5d428-b853-4312-837c-9d66371dd5dc）</em></p><hr>',14)),o("p",null,[t[25]||(t[25]=s("via: ",-1)),n(r,{href:"https://itsfoss.com/bitwarden-vs-proton-pass/"},{default:a(()=>[...t[24]||(t[24]=[s("https://itsfoss.com/bitwarden-vs-proton-pass/",-1)])]),_:1})]),o("p",null,[t[30]||(t[30]=s("作者：",-1)),n(r,{href:"https://itsfoss.com/author/ankush/"},{default:a(()=>[...t[26]||(t[26]=[s("Ankush Das",-1)])]),_:1}),t[31]||(t[31]=s(" 選題：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[27]||(t[27]=[s("lujun9972",-1)])]),_:1}),t[32]||(t[32]=s(" 譯者：",-1)),n(r,{href:"https://linux.cn/lctt/ChatGPT"},{default:a(()=>[...t[28]||(t[28]=[s("ChatGPT",-1)])]),_:1}),t[33]||(t[33]=s(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[29]||(t[29]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[36]||(t[36]=s("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[34]||(t[34]=[s("LCTT",-1)])]),_:1}),t[37]||(t[37]=s(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:a(()=>[...t[35]||(t[35]=[s("Linux中國",-1)])]),_:1}),t[38]||(t[38]=s(" 榮譽推出",-1))])])}const x=i(g,[["render",P]]);export{h as __pageData,x as default};
